package br.com.confirmacao.admin.application;
import br.com.confirmacao.patient.application.*;import br.com.confirmacao.patient.domain.*;import br.com.confirmacao.patient.infrastructure.PatientRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.UUID;
@Service public class AdminPatientService{private final PatientRepository patients;public AdminPatientService(PatientRepository p){patients=p;}@Transactional public Patient update(UUID id,String name,LocalDate birth,String phone,String email,PreferredContactChannel channel){Patient patient=find(id);UUID professionalId=patient.getProfessional().getId();String normalized=phone==null?null:phone.replaceAll("\\D","");if(patients.existsByProfessionalIdAndPhoneAndIdNot(professionalId,normalized,id))throw new PatientAlreadyExistsException();patient.update(name,birth,phone,email,channel);return patient;}@Transactional public void activate(UUID id){find(id).activate();}@Transactional public void deactivate(UUID id){find(id).deactivate();}private Patient find(UUID id){return patients.findById(id).orElseThrow(()->new PatientNotFoundException(id));}}
